arguments.command:
cd /app && cat > app/javascript/controllers/inline_save_controller.js <<'EOF'
import { Controller } from "@hotwired/stimulus"

// Saves made in place on a page (the "Active" switch, "Move up" / "Move down",
// "Delete") must not get lost when the moderator moves on right away.
//
// Turbo aborts a running form submission as soon as a new visit starts, so these
// forms are sent here instead: one after the other, with fetch({ keepalive: true })
// which survives leaving the page. While a save is running, Turbo requests (link
// visits, other forms) wait for it, so the next page always shows the saved state.
//
// The server answers with Turbo Stream actions that update the page in place.
const pending = new Set()
let queue = Promise.resolve()

function enqueue(task) {
  const run = queue.then(task)
  queue = run.catch(() => {})
  pending.add(run)
  run.finally(() => pending.delete(run))
  return run
}

document.addEventListener("turbo:before-fetch-request", (event) => {
  if (pending.size === 0) return

  event.preventDefault()
  Promise.allSettled([ ...pending ]).then(() => event.detail.resume())
})

export default class extends Controller {
  submit(event) {
    const form = event.target
    if (!(form instanceof HTMLFormElement)) return

    event.preventDefault()
    event.stopPropagation()

    const message = form.dataset.confirm
    if (message && !window.confirm(message)) return

    const body = new FormData(form, event.submitter ?? undefined)
    enqueue(() => this.send(form.action, body))
  }

  async send(url, body) {
    let response
    try {
      response = await fetch(url, {
        method: "POST",
        body,
        keepalive: true,
        credentials: "same-origin",
        headers: { Accept: "text/vnd.turbo-stream.html, text/html", "X-CSRF-Token": csrfToken() }
      })
    } catch (error) {
      console.error("Could not save", error)
    }

    if (!this.element.isConnected) return

    const contentType = response?.headers.get("Content-Type") ?? ""
    if (response?.ok && contentType.startsWith("text/vnd.turbo-stream.html")) {
      window.Turbo.renderStreamMessage(await response.text())
    } else {
      // Something went wrong (or no stream came back): show the saved state.
      window.Turbo.visit(window.location.href, { action: "replace" })
    }
  }
}

function csrfToken() {
  return document.querySelector("meta[name=csrf-token]")?.content ?? ""
}
EOF
